// Helper functions
export const getCountyBySlug = (stateSlug: string, countySlug: string): CountyData | undefined => {
  const stateData = stateCountyData.find(s => s.stateSlug === stateSlug);
  return stateData?.counties.find(c => c.slug === countySlug);
};

export const getStateCountyData = (stateSlug: string): StateCountyData | undefined => {
  return stateCountyData.find(s => s.stateSlug === stateSlug);
};

export const getAllCountySlugs = (): { stateSlug: string; countySlug: string }[] => {
  const slugs: { stateSlug: string; countySlug: string }[] = [];
  stateCountyData.forEach(state => {
    state.counties.forEach(county => {
      slugs.push({ stateSlug: state.stateSlug, countySlug: county.slug });
    });
  });
  return slugs;
};

export const getCountiesForState = (stateSlug: string): CountyData[] => {
  return stateCountyData.find(s => s.stateSlug === stateSlug)?.counties || [];
};

export const getTotalCountyCount = (): number => {
  return stateCountyData.reduce((sum, state) => sum + state.counties.length, 0);
};
